import{_ as r,o as e,c as t,a5 as o}from"./chunks/framework.Cooo9kuv.js";const p=JSON.parse('{"title":"WordPress 插件清理工具 — WP Plugin Cleanup","description":"","frontmatter":{"标题":"WordPress 插件清理工具 — WP Plugin Cleanup – wp_chajianqingli","日期":"2026-07-12T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["wordpress主题插件"],"标签":["WordPress","孤立选项","定时任务","插件残留","数据库优化","数据库清理","数据表清理","文章元数据","瞬态缓存"]},"headers":[],"relativePath":"md/wordpress主题插件/WordPress 插件清理工具 — WP Plugin Cleanup - wp_chajianqingli.md","filePath":"md/wordpress主题插件/WordPress 插件清理工具 — WP Plugin Cleanup - wp_chajianqingli.md"}'),n={name:"md/wordpress主题插件/WordPress 插件清理工具 — WP Plugin Cleanup - wp_chajianqingli.md"};function d(s,a,i,l,h,b){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="wordpress-插件清理工具-—-wp-plugin-cleanup" tabindex="-1">WordPress 插件清理工具 — WP Plugin Cleanup <a class="header-anchor" href="#wordpress-插件清理工具-—-wp-plugin-cleanup" aria-label="Permalink to &quot;WordPress 插件清理工具 — WP Plugin Cleanup&quot;">​</a></h1><blockquote><p>扫描并清理已卸载或停用插件遗留在 WordPress 数据库中的冗余数据，包括孤立选项、定时任务、自定义数据表、过期瞬态缓存和文章元数据，释放数据库空间，保持站点数据库整洁。</p></blockquote><p><strong>版本</strong>：v1.0.0<br><strong>适配</strong>：WordPress 5.8+<br><strong>PHP</strong>：≥ 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/4111cd5c-2c3d-41c9-82af-e9d17573a288.png" alt=""></p><p>当您在 WordPress 中安装、使用、然后卸载插件时，很多插件并不会彻底清理自己在数据库中写入的数据。久而久之，<code>wp_options</code> 表中会堆积大量孤立选项，<code>wp_cron</code> 中残留无效的定时任务，数据库中遗留不再使用的自定义数据表，以及过期的瞬态缓存和孤立文章元数据。</p><p>本插件专门解决这一问题：自动扫描 WordPress 数据库中所有可能属于已移除插件的残留数据，按模块分类展示详细信息，让您在清理前充分了解每条数据的来源和风险等级，确认无误后一键删除。</p><p>插件内置五组独立扫描模块，每项数据标注风险等级（安全 / 注意 / 危险）和疑似来源插件，所有清理操作记录到操作日志，支持按成功或失败筛选查看。界面支持中文、英文及自动检测三种语言模式。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="五大扫描模块-独立开关控制" tabindex="-1">五大扫描模块，独立开关控制 <a class="header-anchor" href="#五大扫描模块-独立开关控制" aria-label="Permalink to &quot;五大扫描模块，独立开关控制&quot;">​</a></h3><p>插件提供五组扫描模块，每组模块配有独立的滑动开关，您可以按需启用或禁用任意模块，扫描时仅处理已启用的模块：</p><table tabindex="0"><thead><tr><th>模块</th><th>扫描内容</th><th>风险等级</th></tr></thead><tbody><tr><td>孤立选项</td><td>扫描 <code>wp_options</code> 表中的插件残留选项，自动排除 WordPress 核心选项、活跃插件选项和当前主题选项</td><td>注意</td></tr><tr><td>孤立定时任务</td><td>检测回调函数已缺失但仍残留在 Cron 计划中的定时任务钩子</td><td>安全</td></tr><tr><td>孤立数据表</td><td>查找不属于 WordPress 核心且不匹配任何活跃插件的自定义数据库表，同时显示行数、数据大小和存储引擎</td><td>危险</td></tr><tr><td>过期瞬态缓存</td><td>查找已超过过期时间的 <code>_transient_</code> 和 <code>_site_transient_</code> 条目，支持常规和站点级瞬态</td><td>安全</td></tr><tr><td>过期瞬态缓存</td><td>查找已超过过期时间的 <code>_transient_</code> 和 <code>_site_transient_</code> 条目，支持常规和站点级瞬态</td><td>安全</td></tr></tbody></table><h3 id="智能插件归属推测" tabindex="-1">智能插件归属推测 <a class="header-anchor" href="#智能插件归属推测" aria-label="Permalink to &quot;智能插件归属推测&quot;">​</a></h3><p>每条扫描结果都会自动分析其名称前缀或钩子名称，与当前已安装的插件目录名进行匹配，推测该数据最可能来自哪个插件，并在扫描结果表格的「疑似插件」列中展示，帮助您快速判断数据来源。</p><h3 id="三级风险标识" tabindex="-1">三级风险标识 <a class="header-anchor" href="#三级风险标识" aria-label="Permalink to &quot;三级风险标识&quot;">​</a></h3><p>每个扫描项均标注风险等级，以不同颜色徽章区分：</p><p>— <strong>安全（绿色）</strong>：过期瞬态缓存、无回调的定时任务，可放心删除；<br> — <strong>注意（黄色）</strong>：孤立选项、孤立文章元数据，建议复查后删除；<br> — <strong>危险（红色）</strong>：孤立数据表，执行 DROP TABLE 将永久丢失全部数据，需格外谨慎。</p><h3 id="先预览再清理-多重确认机制" tabindex="-1">先预览再清理，多重确认机制 <a class="header-anchor" href="#先预览再清理-多重确认机制" aria-label="Permalink to &quot;先预览再清理，多重确认机制&quot;">​</a></h3><p>— 扫描结果以表格形式展示，列出每项数据的关键字段（如选项名称、值预览、行数、大小、过期时间等），一目了然；<br> — 每个模块支持「全选」和「取消全选」快捷操作，也可逐项勾选需要清理的数据；<br> — 点击「执行选中清理」后弹出确认对话框，防止误操作；<br> — 当选中项包含数据表或文章元数据时，会额外弹出二次确认提醒；<br> — 只有经过您明确确认的数据才会被删除，不做任何自动清理。</p><h3 id="完整操作日志" tabindex="-1">完整操作日志 <a class="header-anchor" href="#完整操作日志" aria-label="Permalink to &quot;完整操作日志&quot;">​</a></h3><p>每次清理操作都会记录到操作日志中，包含执行时间、操作类型、处理目标和成功或失败状态：</p><p>— 日志以可折叠面板展示，默认收起不占用页面空间；<br> — 支持按「全部」「成功」「失败」三个标签页筛选查看；<br> — 日志条数上限可在设置中配置（默认 100 条），超出后自动移除旧记录；<br> — 提供「清除日志」按钮一键清空所有记录。</p><h3 id="中英双语界面" tabindex="-1">中英双语界面 <a class="header-anchor" href="#中英双语界面" aria-label="Permalink to &quot;中英双语界面&quot;">​</a></h3><p>插件内置完整的中英文翻译对照表，通过 <code>gettext</code> 过滤器实现界面语言切换：</p><p>— 支持中文、English、自动检测三种模式；<br> — 自动检测模式下，根据 WordPress 站点语言自动匹配中文或英文；<br> — 语言切换通过页面顶部工具栏的下拉选择框即时切换，无需刷新。</p><h3 id="安全设计" tabindex="-1">安全设计 <a class="header-anchor" href="#安全设计" aria-label="Permalink to &quot;安全设计&quot;">​</a></h3><p>— 所有删除操作必须经过用户勾选和二次确认，不做任何自动清理；<br> — 选项扫描自动排除 WordPress 核心选项、活跃插件前缀匹配的选项、当前主题前缀匹配的选项以及自身插件选项；<br> — 定时任务扫描自动排除 WordPress 核心 Cron 钩子（<code>wp_</code>、<code>recovery_mode_</code> 等）；<br> — 数据表扫描仅在名称不匹配任何活跃插件 slug 时才标记为孤立；<br> — 文章元数据扫描自动排除 <code>_wp_</code>、<code>_edit_</code>、<code>_thumbnail_id</code>、<code>_menu_item_</code> 等 WordPress 核心元数据键；<br> — 卸载插件时自动清理自身配置数据，不留残留。</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>wp-plugin-cleanup</code> 文件夹上传至网站 <code>/wp-content/plugins/</code> 目录，进入 WordPress 后台「插件」页面，找到「WP Plugin Cleanup」并点击启用。</p><h3 id="第二步-配置扫描模块" tabindex="-1">第二步：配置扫描模块 <a class="header-anchor" href="#第二步-配置扫描模块" aria-label="Permalink to &quot;第二步：配置扫描模块&quot;">​</a></h3><p>进入后台左侧菜单「插件清理」，在页面顶部的「扫描模块设置」卡片中：</p><p>— 通过滑动开关启用或禁用您需要扫描的模块（默认全部启用）；<br> — 点击「保存更改」使配置生效。</p><h3 id="第三步-执行扫描" tabindex="-1">第三步：执行扫描 <a class="header-anchor" href="#第三步-执行扫描" aria-label="Permalink to &quot;第三步：执行扫描&quot;">​</a></h3><p>— 点击「一键扫描全部」按钮对所有已启用模块执行扫描；<br> — 也可以在每个模块卡片的标题栏右侧点击「扫描」按钮单独扫描该模块；<br> — 扫描过程中页面显示全屏加载遮罩，防止重复提交；<br> — 扫描完成后自动刷新页面，各模块卡片展开显示扫描结果。</p><h3 id="第四步-审查结果" tabindex="-1">第四步：审查结果 <a class="header-anchor" href="#第四步-审查结果" aria-label="Permalink to &quot;第四步：审查结果&quot;">​</a></h3><p>— 查看每个模块卡片中的扫描结果表格，重点关注「疑似插件」列和「风险等级」列；<br> — 使用「全选」或「取消全选」快捷链接批量操作，或逐项勾选需要清理的数据；<br> — 对标记为「危险」的数据表，请务必在删除前确认该表确实不再需要。</p><h3 id="第五步-执行清理" tabindex="-1">第五步：执行清理 <a class="header-anchor" href="#第五步-执行清理" aria-label="Permalink to &quot;第五步：执行清理&quot;">​</a></h3><p>— 勾选完成后点击页面底部的红色「执行选中清理」按钮；<br> — 在弹出的确认对话框中点击确定；<br> — 如果选中项包含数据表，会弹出第二次确认对话框；<br> — 如果选中项包含文章元数据，同样会弹出额外确认；<br> — 清理完成后页面显示操作结果统计（成功 / 失败 / 跳过数量）。</p><h3 id="第六步-查看日志" tabindex="-1">第六步：查看日志 <a class="header-anchor" href="#第六步-查看日志" aria-label="Permalink to &quot;第六步：查看日志&quot;">​</a></h3><p>— 页面底部「操作日志」面板可展开查看所有清理记录；<br> — 点击「成功」或「失败」标签筛选对应状态的日志条目；<br> — 日志保留条数可在模块设置中调整，默认为 100 条。</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 本插件仅清理数据库中的残留数据，不会修改任何插件文件或 WordPress 核心文件；<br> — 清理操作不可撤销，执行前请务必仔细审查扫描结果；<br> — 删除数据表（DROP TABLE）会永久丢失该表中的所有数据，请格外谨慎；<br> — 如果某个插件只是暂时停用而非卸载，其产生的选项和数据表不会被标记为孤立（因为插件目录仍然存在）；<br> — 建议在清理前备份数据库，以防误删重要数据；<br> — 插件自身在卸载时会自动删除所有配置数据和日志记录，不会在数据库中留下残留。</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.top<br> — 作者网站：softbangong.com<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a><br> — 邮箱：<a href="mailto:softbangong@gmail.com" target="_blank" rel="noreferrer">softbangong@gmail.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-0-0-2026-07-12" tabindex="-1">v1.0.0（2026-07-12） <a class="header-anchor" href="#v1-0-0-2026-07-12" aria-label="Permalink to &quot;v1.0.0（2026-07-12）&quot;">​</a></h3><p>— 首次发布；<br> — 实现孤立选项扫描模块，自动排除 WordPress 核心选项、活跃插件和主题选项；<br> — 实现孤立定时任务扫描模块，检测回调函数缺失的 Cron 钩子；<br> — 实现孤立数据表扫描模块，显示行数、数据大小和存储引擎信息；<br> — 实现过期瞬态缓存扫描模块，支持常规和站点级瞬态；<br> — 实现孤立文章元数据扫描模块，自动排除核心元数据键；<br> — 五组扫描模块均配备独立滑动开关，支持按需启用或禁用；<br> — 扫描结果以表格展示，含疑似插件推测和三级风险标识；<br> — 清理操作需多重确认，DROP TABLE 和 Post Meta 删除额外二次确认；<br> — 完整操作日志记录，支持按成功或失败筛选查看；<br> — 中英双语界面，支持自动检测语言模式。</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/3051.html" target="_blank" rel="noreferrer">https://www.softbangong.com/3051.html</a></p>',50)])])}const u=r(n,[["render",d]]);export{p as __pageData,u as default};
